import{_ as a,o as s,c as r,ag as t}from"./chunks/framework.DC2M1AAK.js";const g=JSON.parse('{"title":"ADR 0002 — Durable stores with graceful fallback","description":"","frontmatter":{},"headers":[],"relativePath":"reference/adr/0002-durable-stores.md","filePath":"reference/adr/0002-durable-stores.md"}'),o={name:"reference/adr/0002-durable-stores.md"};function n(i,e,l,d,c,u){return s(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0002-—-durable-stores-with-graceful-fallback" tabindex="-1">ADR 0002 — Durable stores with graceful fallback <a class="header-anchor" href="#adr-0002-—-durable-stores-with-graceful-fallback" aria-label="Permalink to &quot;ADR 0002 — Durable stores with graceful fallback&quot;">​</a></h1><ul><li><strong>Status:</strong> Accepted</li><li><strong>Date:</strong> 2026-08-09 (origin)</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Rate limits, usage caps, sessions and the usage ledger lived in process memory. In a multi-node deploy, in-memory limits silently multiply by node count (a correctness bug, not a nicety), sessions created on one node 410 on another, and billing needs a durable ledger.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><ul><li><strong>Redis</strong> (<code>AGENT_REDIS_URL</code>) for atomic fixed-window counters: INCRBY + PEXPIRE NX gives a window that starts at first use and resets when it expires, correct across nodes. Used by rate limits and usage caps.</li><li><strong>MongoDB</strong> (<code>AGENT_MONGO_URL</code>) for sessions (lazily hydrated, never bulk-loaded), the <code>usage_events</code> ledger and the <code>events</code> product ledger.</li><li><strong>Unset or unreachable ⇒ in-memory counters, file sessions, JSONL ledgers</strong>, with a warning — a laptop and CI need no services. <code>/api/health</code> shows which backend is live.</li><li>Deliberately process-local even with Redis: in-flight guards (one turn per session, a global cap) and per-node metrics — sticky sessions are the recommendation.</li><li>Ledger writes are fire-and-forget: an outage loses ledger events, never blocks a chat.</li><li>node-redis reconnects forever: the initial connect is bounded (4 s) or startup hangs.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><p>New shared counters go through <code>getCounterStore()</code>; never a process-local Map for anything that must be shared. Multi-node deployments set both URLs; the checklist says so.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/docs/adr/0002-durable-stores.md">docs/adr/0002-durable-stores.md</a> — edit it there; the site mirrors the repository.</small></p>',10)])])}const b=a(o,[["render",n]]);export{g as __pageData,b as default};
